export const ACTIONS=[
 ['forward','Move forward','Movement','KeyW','KeyW'],['back','Move backward','Movement','KeyS','KeyS'],['left','Strafe left','Movement','KeyA','KeyA'],['right','Strafe right','Movement','KeyD','KeyD'],['jump','Jump','Movement','Space','Space'],['sprint','Sprint','Movement','ShiftLeft','ShiftLeft','ShiftRight'],['crouch','Crouch','Movement','KeyC','KeyC','ControlLeft'],
 ['fire','Fire','Combat','MouseLeft','MouseLeft'],['aim','Aim','Combat','MouseRight','MouseRight'],['reload','Reload','Combat','KeyR','KeyR'],['grenade','Throw grenade','Combat','KeyG','KeyG'],['streak','Use killstreak','Combat','KeyF','KeyF'],['slow','Slow motion','Combat','KeyQ','KeyQ'],
 ...Array.from({length:6},(_,i)=>['weapon'+(i+1),'Weapon '+(i+1),'Weapons','Digit'+(i+1),'Digit'+(i+1)]),['previous','Previous weapon','Weapons','PreviousWeapon','WheelUp'],['next','Next weapon','Weapons','NextWeapon','WheelDown'],
 ['scores','Scoreboard','Game','Tab','Tab'],['pause','Pause','Game','Escape','Escape'],['lookLeft','Look left','Look keys','ArrowLeft','ArrowLeft'],['lookRight','Look right','Look keys','ArrowRight','ArrowRight'],['lookUp','Look up','Look keys','ArrowUp','ArrowUp'],['lookDown','Look down','Look keys','ArrowDown','ArrowDown']
].map(([id,label,group,code,first,second=''])=>({id,label,group,code,defaults:[first,second]}));
export const mouseCode=button=>['MouseLeft','MouseMiddle','MouseRight','Mouse4','Mouse5'][button]||'Mouse'+(button+1);
export function keyLabel(code){return ({MouseLeft:'MOUSE 1',MouseRight:'MOUSE 2',MouseMiddle:'MOUSE 3',Mouse4:'MOUSE 4',Mouse5:'MOUSE 5',WheelUp:'WHEEL ↑',WheelDown:'WHEEL ↓',ShiftLeft:'L SHIFT',ShiftRight:'R SHIFT',ControlLeft:'L CTRL',ControlRight:'R CTRL',AltLeft:'L ALT',AltRight:'R ALT',ArrowUp:'↑',ArrowDown:'↓',ArrowLeft:'←',ArrowRight:'→',Space:'SPACE',Escape:'ESC',Backspace:'BACKSPACE'})[code]||code.replace(/^Key|^Digit/,'').replace(/([a-z])([A-Z])/g,'$1 $2').toUpperCase()||'—'}
export class ControlBindings{
 constructor(saved){this.bindings={};for(const a of ACTIONS){const values=saved?.[a.id];this.bindings[a.id]=[0,1].map(i=>values&&Array.isArray(values)?typeof values[i]==='string'&&/^[A-Za-z0-9]{0,30}$/.test(values[i])?values[i]:'':a.defaults[i])}const used=new Set();for(const a of ACTIONS)for(let i=0;i<2;i++){const c=this.bindings[a.id][i];if(c&&used.has(c))this.bindings[a.id][i]='';else if(c)used.add(c)}}
 actionsFor(code){return ACTIONS.filter(a=>this.bindings[a.id].includes(code))}
 conflicts(code,id,slot){return code?ACTIONS.flatMap(a=>this.bindings[a.id].flatMap((c,i)=>c===code&&!(a.id===id&&i===slot)?[{id:a.id,slot:i,label:a.label}]:[])):[]}
 assign(id,slot,code,replace=false){if(!this.bindings[id]||![0,1].includes(slot)||!/^[A-Za-z0-9]{0,30}$/.test(code))return false;const conflicts=this.conflicts(code,id,slot);if(conflicts.length&&!replace)return conflicts;for(const c of conflicts)this.bindings[c.id][c.slot]='';this.bindings[id][slot]=code;return true}
}
export function bindingsHTML(controls,settings,pending=null,message=''){
 return `<div class="controls-toolbar"><label>Mouse sensitivity <input id="control-sensitivity" type="range" min="0.2" max="3" step="0.05" value="${settings.sensitivity||1}"><output>${(settings.sensitivity||1).toFixed(2)}×</output></label><label><input id="control-invert" type="checkbox" ${settings.invertY?'checked':''}> Invert mouse Y</label><label>Crouch <select id="control-crouch"><option value="hold" ${!settings.crouchToggle?'selected':''}>Hold</option><option value="toggle" ${settings.crouchToggle?'selected':''}>Toggle</option></select></label></div><div class="binding-grid">${['Movement','Combat','Weapons','Game','Look keys'].map(group=>`<section class="binding-group"><h3>${group}<small>PRIMARY / SECONDARY</small></h3>${ACTIONS.filter(a=>a.group===group).map(a=>`<div class="binding-row"><span>${a.label}</span>${controls.bindings[a.id].map((c,i)=>`<button data-binding="${a.id}:${i}" aria-label="${a.label}, ${i?'secondary':'primary'}: ${keyLabel(c)}">${keyLabel(c)}</button>`).join('')}</div>`).join('')}</section>`).join('')}</div><div class="binding-status" role="status">${message||''}</div>${pending?`<div class="binding-modal"><div><small>${ACTIONS.find(a=>a.id===pending.id).label} · ${pending.slot?'SECONDARY':'PRIMARY'}</small><h3>${pending.code?keyLabel(pending.code):'PRESS A KEY OR MOUSE BUTTON'}</h3><p>${pending.conflicts?.length?`Assigned to ${pending.conflicts.map(c=>c.label).join(', ')}. Replace?`:'Mouse wheel supported. Escape cancels.'}</p><div>${pending.code?'<button id="bind-replace">REPLACE BINDING</button>':'<button id="bind-clear">CLEAR BINDING</button>'}<button id="bind-escape">USE ESC</button><button id="bind-cancel">CANCEL</button></div></div></div>`:''}`;
}
